    def minDistance(self, word1: str, word2: str) -> int:
        m = len(word1)
        n = len(word2)
        a = []
        for i in range(m+1):
            a.append([])
            for j in range(n+1):
                a[-1].append(0)

        for i in range(m):
            for j in range(n):
                if word1[i]==word2[j]:
                    a[i+1][j+1] = 1 + a[i][j]
                else:
