class Solution:
    def fractionAddition(self, expression: str) -> str:
        expression = expression.replace('-', '+-')
        parts = [item for item in expression.split('+') if item != '']
        numes, denoms, denom_set, lcm = [], [], set(), 1
        def get_lcm(a, b):
            if a == 1:
                return b
            if b == 1:
                return a
            if a < b:
                if b % a == 0:
                    return a * get_lcm(1, b/a)
                else:
                    return a * get_lcm(1, b)
            else:
                if a % b == 0:
                    return b * get_lcm(a/b, 1)
                else:
                    return b * get_lcm(a, 1)

        for part in parts:
            num, den = part.split('/')
            numes.append(int(num))
            denoms.append(int(den))
            lcm = get_lcm(lcm, int(den))

        result = 0
        for num, den in zip(numes, denoms):
             result +=num * int(lcm/den)

        def get_gcd(a, b):
            if a == 0:
                return b
            if b == 0:
                return a
            if a == b:
                return a
            elif a < b:
                return get_gcd(a, b-a)
            else:
                return get_gcd(a-b, b)

        gcd = get_gcd(abs(result), lcm)
        return str(int(result/gcd)) + '/' + str(int(lcm/gcd))

class Solution:
    def validSquare(self, p1, p2, p3, p4):

        def cal(A, B):
            return abs(A[0] - B[0]) + abs(A[1] - B[1])

        d = [cal(p1, p2), cal(p1, p3), cal(p1, p4), cal(p2, p3), cal(p2, p4), cal(p3, p4)]
        d.sort()

        return 0 < d[0] == d[1] == d[2] == d[3] and d[4] == d[5]

class Solution:
    def validSquare(self, p1, p2, p3, p4):
        def dist(p1, p2):
            return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

        lookup = set([dist(p1, p2), dist(p1, p3),\
                      dist(p1, p4), dist(p2, p3),\
                      dist(p2, p4), dist(p3, p4)])
        return 0 not in lookup and len(lookup) == 2

